From 66a5f81639d84cd94dd372ba46fc7c08997e019f Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sun, 22 Nov 2026 00:41:02 +0100
Subject: [PATCH] folder: make delete confirmations modal to the desktop

Folder View started its delete, trash and empty trash jobs without a
window, so their confirmation wasn't modal and each key press opened
another dialog. Give the jobs the view's window so KIO makes it modal.

BUG: 387988
---
 containments/desktop/plugins/folder/CMakeLists.txt |  1 +
 .../desktop/plugins/folder/foldermodel.cpp         | 14 ++++++++++++++
 containments/desktop/plugins/folder/foldermodel.h  |  2 ++
 3 files changed, 17 insertions(+)

diff --git a/containments/desktop/plugins/folder/CMakeLists.txt b/containments/desktop/plugins/folder/CMakeLists.txt
index 9ddc1fc400..effb591b46 100644
--- a/containments/desktop/plugins/folder/CMakeLists.txt
+++ b/containments/desktop/plugins/folder/CMakeLists.txt
@@ -32,6 +32,7 @@ target_link_libraries(folderplugin PUBLIC
                       Qt::Quick
                       Plasma::Activities
                       KF6::CoreAddons
+                      KF6::GuiAddons
                       KF6::KIOCore
                       KF6::KIOWidgets
                       KF6::KIOFileWidgets
diff --git a/containments/desktop/plugins/folder/foldermodel.cpp b/containments/desktop/plugins/folder/foldermodel.cpp
index 678bae687c..952cb39c9f 100644
--- a/containments/desktop/plugins/folder/foldermodel.cpp
+++ b/containments/desktop/plugins/folder/foldermodel.cpp
@@ -66,6 +66,7 @@
 #include <KIO/PreviewJob>
 #include <KIO/RestoreJob>
 #include <KIO/StatJob>
+#include <KJobWindows>
 #include <kio_version.h>
 #if KIO_VERSION >= QT_VERSION_CHECK(6, 31, 0)
 #include <KIO/RenameFileWarningDialog>
@@ -2389,6 +2390,16 @@ void FolderModel::setShowHiddenFiles(bool enable)
     }
 }

+QWindow *FolderModel::viewWindow() const
+{
+    if (auto *adapter = qobject_cast<ItemViewAdapter *>(m_viewAdapter)) {
+        if (auto *item = qobject_cast<QQuickItem *>(adapter->adapterView())) {
+            return item->window();
+        }
+    }
+    return nullptr;
+}
+
 void FolderModel::moveSelectedToTrash()
 {
     if (!m_selectionModel->hasSelection()) {
@@ -2412,6 +2423,7 @@ void FolderModel::moveSelectedToTrash()
     using Iface = KIO::AskUserActionInterface;
     auto *job = new KIO::DeleteOrTrashJob(selectedUrls(), Iface::Trash, Iface::DefaultConfirmation, this);
     job->setUiDelegate(new KNotificationJobUiDelegate(KJobUiDelegate::AutoHandlingEnabled));
+    KJobWindows::setWindow(job, viewWindow());
     job->start();
 }

@@ -2429,6 +2441,7 @@ void FolderModel::deleteSelected()

     using Iface = KIO::AskUserActionInterface;
     auto *job = new KIO::DeleteOrTrashJob(selectedUrls(), Iface::Delete, Iface::DefaultConfirmation, this);
+    KJobWindows::setWindow(job, viewWindow());
     job->start();
 }

@@ -2446,6 +2459,7 @@ void FolderModel::emptyTrashBin()
 {
     using Iface = KIO::AskUserActionInterface;
     auto *job = new KIO::DeleteOrTrashJob({}, Iface::EmptyTrash, Iface::DefaultConfirmation, this);
+    KJobWindows::setWindow(job, viewWindow());
     job->start();
 }

diff --git a/containments/desktop/plugins/folder/foldermodel.h b/containments/desktop/plugins/folder/foldermodel.h
index c2a2a388f9..c39cb55e9b 100644
--- a/containments/desktop/plugins/folder/foldermodel.h
+++ b/containments/desktop/plugins/folder/foldermodel.h
@@ -34,6 +34,7 @@
 class QDrag;
 class QItemSelectionModel;
 class QQuickItem;
+class QWindow;

 class KFileCopyToMenu;
 class KDirModel;
@@ -368,6 +369,7 @@ private:
     static bool isTrashEmpty();
     static bool isDeleteCommandShown();
     QList<QUrl> selectedUrls() const;
+    QWindow *viewWindow() const;
     KDirModel *m_dirModel;
     KDirWatch *m_dirWatch;
     QString m_url;
-- 
